<?php
declare(strict_types=1);
require_once __DIR__ . '/../src/bootstrap.php';

use P2K\TeamPoints\ChessApi;
use P2K\TeamPoints\Database;
use P2K\TeamPoints\Repository;

@set_time_limit(55);
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');

function dbrepair_json(array $payload, int $status = 200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); echo json_encode($payload, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR); exit; }
function dbrepair_body(): array { $raw=file_get_contents('php://input'); if($raw===false||trim($raw)==='')return[]; $v=json_decode($raw,true,512,JSON_THROW_ON_ERROR); if(!is_array($v))throw new RuntimeException('JSON object required.'); return $v; }
function dbrepair_header(string $name): string { return trim((string)($_SERVER['HTTP_'.strtoupper(str_replace('-','_',$name))]??'')); }
function dbrepair_auth(array $config): void { $expected=trim((string)($config['app']['admin_token']??'')); $provided=dbrepair_header('X-P2K-Admin-Token'); if($expected===''||str_starts_with($expected,'CHANGE_'))throw new RuntimeException('The Team Points administrator token is not configured.'); if($provided===''||!hash_equals($expected,$provided))dbrepair_json(['ok'=>false,'error'=>'Administrator authorization failed.'],403); }
function dbrepair_uuid(): string { $b=random_bytes(16); $b[6]=chr((ord($b[6])&0x0f)|0x40); $b[8]=chr((ord($b[8])&0x3f)|0x80); return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4)); }
function dbrepair_tables(PDO $pdo): void {
    $pdo->exec("CREATE TABLE IF NOT EXISTS p2k_tp_audit_jobs(
      id CHAR(36) NOT NULL PRIMARY KEY,club_slug VARCHAR(120) NOT NULL,mode ENUM('arithmetic','former','full') NOT NULL,
      status ENUM('running','paused','completed','cancelled') NOT NULL DEFAULT 'paused',cursor_match_id BIGINT UNSIGNED NOT NULL DEFAULT 0,
      total_candidates BIGINT UNSIGNED NOT NULL DEFAULT 0,checked_count BIGINT UNSIGNED NOT NULL DEFAULT 0,issue_count BIGINT UNSIGNED NOT NULL DEFAULT 0,
      error_count BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,completed_at DATETIME NULL,last_error TEXT NULL,
      KEY idx_tp_audit_jobs(club_slug,status,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS p2k_tp_audit_issues(
      id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,job_id CHAR(36) NOT NULL,club_slug VARCHAR(120) NOT NULL,match_id BIGINT UNSIGNED NOT NULL,
      issue_type VARCHAR(48) NOT NULL,proposed_action ENUM('remove','review') NOT NULL DEFAULT 'remove',reason TEXT NOT NULL,details_json MEDIUMTEXT NULL,
      status ENUM('pending','repaired','ignored') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,
      UNIQUE KEY uq_tp_audit_issue(job_id,match_id,issue_type),KEY idx_tp_audit_pending(job_id,status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS p2k_tp_consistency_repairs(
      id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,repair_run_id CHAR(36) NOT NULL,club_slug VARCHAR(120) NOT NULL,match_id BIGINT UNSIGNED NOT NULL,
      action VARCHAR(24) NOT NULL,reason TEXT NULL,before_json MEDIUMTEXT NULL,after_json MEDIUMTEXT NULL,created_at DATETIME NOT NULL,
      KEY idx_tp_consistency_run(repair_run_id,id),KEY idx_tp_consistency_match(club_slug,match_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
function dbrepair_job(PDO $pdo,string $id,string $club): ?array { $q=$pdo->prepare('SELECT * FROM p2k_tp_audit_jobs WHERE id=? AND club_slug=? LIMIT 1');$q->execute([$id,$club]);$r=$q->fetch();return is_array($r)?$r:null; }
function dbrepair_candidate_where(string $mode): string { return $mode==='former' ? "EXISTS(SELECT 1 FROM p2k_tp_participations p JOIN p2k_tp_members m ON m.club_slug=p.club_slug AND m.username_key=p.username_key AND m.current_member=0 WHERE p.club_slug=s.club_slug AND p.match_id=s.match_id)" : '1=1'; }
function dbrepair_total(PDO $pdo,string $club,string $mode): int { $q=$pdo->prepare('SELECT COUNT(*) FROM p2k_tp_match_summaries s WHERE s.club_slug=? AND '.dbrepair_candidate_where($mode));$q->execute([$club]);return (int)$q->fetchColumn(); }
function dbrepair_candidate_ids(PDO $pdo,string $club,string $mode,int $cursor,int $limit): array { $sql='SELECT s.match_id FROM p2k_tp_match_summaries s WHERE s.club_slug=? AND s.match_id>? AND '.dbrepair_candidate_where($mode).' ORDER BY s.match_id LIMIT '.$limit; $q=$pdo->prepare($sql);$q->execute([$club,$cursor]);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)?:[]); }
function dbrepair_details(PDO $pdo,string $club,int $matchId): ?array {
    $q=$pdo->prepare("SELECT s.*,m.status AS metadata_status,m.board_count AS authoritative_boards,m.p2k_score,m.opponent_score,m.match_name,m.match_url,
      (SELECT COUNT(*) FROM p2k_tp_participations p WHERE p.club_slug=s.club_slug AND p.match_id=s.match_id) AS discovered_boards,
      (SELECT COUNT(*) FROM p2k_tp_point_events e WHERE e.club_slug=s.club_slug AND e.match_id=s.match_id) AS event_games,
      (SELECT COALESCE(SUM(e.points),0) FROM p2k_tp_point_events e WHERE e.club_slug=s.club_slug AND e.match_id=s.match_id) AS event_score,
      (SELECT COUNT(*) FROM (SELECT p2.club_slug,p2.match_id,p2.board_url,COUNT(e2.game_url) c FROM p2k_tp_participations p2 LEFT JOIN p2k_tp_point_events e2 ON e2.club_slug=p2.club_slug AND e2.match_id=p2.match_id AND e2.board_url=p2.board_url WHERE p2.club_slug=? AND p2.match_id=? GROUP BY p2.club_slug,p2.match_id,p2.board_url HAVING c<>2) bad) AS invalid_boards
      FROM p2k_tp_match_summaries s LEFT JOIN p2k_tp_match_metadata m ON m.club_slug=s.club_slug AND m.match_id=s.match_id WHERE s.club_slug=? AND s.match_id=? LIMIT 1");
    $q->execute([$club,$matchId,$club,$matchId]);$r=$q->fetch();return is_array($r)?$r:null;
}
function dbrepair_club_team(array $match,string $club): ?array { foreach((array)($match['teams']??[]) as $team){if(!is_array($team))continue;foreach(['@id','url'] as $f){$v=strtolower(rtrim((string)($team[$f]??''),'/'));if(str_ends_with($v,'/club/'.strtolower($club)))return $team;}}return null; }
function dbrepair_issue(PDO $pdo,array $job,int $matchId,string $type,string $action,string $reason,array $details=[]): void { $q=$pdo->prepare("INSERT INTO p2k_tp_audit_issues(job_id,club_slug,match_id,issue_type,proposed_action,reason,details_json,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'pending',UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE proposed_action=VALUES(proposed_action),reason=VALUES(reason),details_json=VALUES(details_json),status=IF(status='repaired','repaired','pending'),updated_at=UTC_TIMESTAMP()");$q->execute([$job['id'],$job['club_slug'],$matchId,$type,$action,$reason,json_encode($details,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]); }
function dbrepair_arithmetic(PDO $pdo,array $job,int $id): bool {
    $r=dbrepair_details($pdo,$job['club_slug'],$id); if(!$r)return false; $reasons=[];$b=(int)($r['authoritative_boards']??0);$expected=$b*2;
    if($b<=0)$reasons[]='Authoritative board count is missing from match metadata.';
    else {
      if((int)$r['board_count']!==$b)$reasons[]="Summary boards {$r['board_count']} differ from authoritative boards {$b}.";
      if((int)$r['discovered_boards']!==$b)$reasons[]="Discovered boards {$r['discovered_boards']} differ from authoritative boards {$b}.";
      if((int)$r['game_count']!==$expected)$reasons[]="Summary games {$r['game_count']} differ from expected {$expected}.";
      if((int)$r['event_games']!==$expected)$reasons[]="Stored game events {$r['event_games']} differ from expected {$expected}.";
      if((int)$r['invalid_boards']>0)$reasons[]="{$r['invalid_boards']} board(s) do not contain exactly two games.";
      if(abs(((float)$r['p2k_score']+(float)$r['opponent_score'])-$expected)>0.001)$reasons[]='The two team scores do not sum to two points per board.';
      if(abs((float)$r['team_score']-(float)$r['event_score'])>0.001)$reasons[]='Summary score differs from stored P2K game-event points.';
      $expectedResult=(float)$r['team_score']>$b?'win':(abs((float)$r['team_score']-$b)<0.001?'draw':'loss');$expectedPoints=$expectedResult==='win'?5*$b:($expectedResult==='draw'?2*$b:0);
      if((string)$r['result']!==$expectedResult||(int)$r['competition_points']!==$expectedPoints)$reasons[]='Stored result or competition points do not match the board-count formula.';
    }
    if(strtolower((string)($r['metadata_status']??''))!=='finished')$reasons[]='Stored match metadata does not report status finished.';
    if(!$reasons)return false; dbrepair_issue($pdo,$job,$id,'arithmetic_mismatch','remove',implode(' ',$reasons),$r);return true;
}
function dbrepair_authoritative(PDO $pdo,Repository $repo,array $job,int $id): bool {
    try{$api=new ChessApi($repo);$m=$api->json('https://api.chess.com/pub/match/'.$id,true);$team=dbrepair_club_team($m,$job['club_slug']);if(!$team)throw new RuntimeException('P2K team not found in the match payload.');$status=strtolower((string)($m['status']??''));$boards=(int)($m['boards']??0);$score=is_numeric($team['score']??null)?(float)$team['score']:null;$local=dbrepair_details($pdo,$job['club_slug'],$id);$reasons=[];if($status!=='finished')$reasons[]="Chess.com reports status {$status}.";if($boards<=0)$reasons[]='Chess.com returned no board count.';if($score===null)$reasons[]='Chess.com returned no P2K score.';if($local&&$boards>0){if((int)$local['board_count']!==$boards)$reasons[]='Summary board count differs from Chess.com.';if((int)$local['discovered_boards']!==$boards)$reasons[]='Discovered board count differs from Chess.com.';if($score!==null&&abs((float)$local['team_score']-$score)>0.001)$reasons[]='Summary P2K score differs from Chess.com.';}if(!$reasons)return false;dbrepair_issue($pdo,$job,$id,'authoritative_mismatch','remove',implode(' ',$reasons),['status'=>$status,'boards'=>$boards,'score'=>$score,'local'=>$local]);return true;}catch(Throwable $e){dbrepair_issue($pdo,$job,$id,'api_retry','review',$e->getMessage(),[]);return true;}
}
function dbrepair_rebuild(PDO $pdo,string $club): void { /* v2.8.0 Analytics totals rebuild lazily after the Core repair commits. */ }
function dbrepair_status(PDO $pdo,array $job): array { $q=$pdo->prepare("SELECT id,match_id,issue_type,proposed_action,reason,details_json,status,created_at,updated_at FROM p2k_tp_audit_issues WHERE job_id=? AND status='pending' ORDER BY id LIMIT 500");$q->execute([$job['id']]);$issues=array_map(static function($r){$r['id']=(int)$r['id'];$r['match_id']=(int)$r['match_id'];unset($r['details_json']);return$r;},$q->fetchAll()?:[]);$count=$pdo->prepare("SELECT COUNT(*) FROM p2k_tp_audit_issues WHERE job_id=? AND status='pending'");$count->execute([$job['id']]);return ['job'=>$job,'issues'=>$issues,'pending_count'=>(int)$count->fetchColumn()]; }

$action=strtolower(trim((string)($_GET['action']??'')));
if($action!==''){
 try{if(strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'))!=='POST')dbrepair_json(['ok'=>false,'error'=>'POST required.'],405);$config=p2k_tp_config();dbrepair_auth($config);$club=strtolower((string)($config['app']['club_slug']??'promote-to-king'));$pdo=Database::connection();$repo=new Repository($pdo);if(!$repo->schemaInstalled())$repo->upgradeExistingSchema(__DIR__.'/../sql/schema.sql');dbrepair_tables($pdo);$body=dbrepair_body();
  if($action==='start'){ $mode=strtolower((string)($body['mode']??'arithmetic'));if(!in_array($mode,['arithmetic','former','full'],true))throw new RuntimeException('Invalid audit mode.');$id=dbrepair_uuid();$total=dbrepair_total($pdo,$club,$mode);$q=$pdo->prepare("INSERT INTO p2k_tp_audit_jobs(id,club_slug,mode,status,total_candidates,created_at,updated_at) VALUES(?,?,?,'running',?,UTC_TIMESTAMP(),UTC_TIMESTAMP())");$q->execute([$id,$club,$mode,$total]);dbrepair_json(['ok'=>true]+dbrepair_status($pdo,dbrepair_job($pdo,$id,$club))); }
  if($action==='latest'){ $q=$pdo->prepare("SELECT * FROM p2k_tp_audit_jobs WHERE club_slug=? AND status<>'cancelled' ORDER BY updated_at DESC LIMIT 1");$q->execute([$club]);$latest=$q->fetch();if(!is_array($latest))dbrepair_json(['ok'=>true,'job'=>null,'issues'=>[],'pending_count'=>0]);dbrepair_json(['ok'=>true]+dbrepair_status($pdo,$latest)); }
  $id=(string)($body['job_id']??'');$job=dbrepair_job($pdo,$id,$club);if(!$job)throw new RuntimeException('Audit job not found.');
  if(in_array($action,['pause','resume','cancel'],true)){ $status=$action==='pause'?'paused':($action==='resume'?'running':'cancelled');$q=$pdo->prepare('UPDATE p2k_tp_audit_jobs SET status=?,updated_at=UTC_TIMESTAMP(),completed_at=IF(? IN (\'completed\',\'cancelled\'),UTC_TIMESTAMP(),completed_at) WHERE id=?');$q->execute([$status,$status,$id]);dbrepair_json(['ok'=>true]+dbrepair_status($pdo,dbrepair_job($pdo,$id,$club))); }
  if($action==='status')dbrepair_json(['ok'=>true]+dbrepair_status($pdo,$job));
  if($action==='step'){if($job['status']!=='running')dbrepair_json(['ok'=>true]+dbrepair_status($pdo,$job));$limit=max(1,min(25,(int)($body['batch']??5)));$ids=dbrepair_candidate_ids($pdo,$club,$job['mode'],(int)$job['cursor_match_id'],$limit);$checked=0;$issues=0;$errors=0;$cursor=(int)$job['cursor_match_id'];foreach($ids as $matchId){$cursor=max($cursor,$matchId);$checked++;try{$found=$job['mode']==='arithmetic'?dbrepair_arithmetic($pdo,$job,$matchId):dbrepair_authoritative($pdo,$repo,$job,$matchId);if($found)$issues++;}catch(Throwable $e){$errors++;dbrepair_issue($pdo,$job,$matchId,'audit_error','review',$e->getMessage());}}$done=count($ids)<$limit;$status=$done?'completed':'running';$q=$pdo->prepare('UPDATE p2k_tp_audit_jobs SET cursor_match_id=?,checked_count=checked_count+?,issue_count=issue_count+?,error_count=error_count+?,status=?,updated_at=UTC_TIMESTAMP(),completed_at=IF(?=\'completed\',UTC_TIMESTAMP(),NULL),last_error=NULL WHERE id=?');$q->execute([$cursor,$checked,$issues,$errors,$status,$status,$id]);dbrepair_json(['ok'=>true]+dbrepair_status($pdo,dbrepair_job($pdo,$id,$club)));}
  if($action==='repair'){ $limit=max(1,min(25,(int)($body['limit']??5)));$selected=array_values(array_filter(array_map('intval',(array)($body['issue_ids']??[]))));$where=$selected?(' AND id IN ('.implode(',',array_fill(0,count($selected),'?')).')'):'';$sql="SELECT * FROM p2k_tp_audit_issues WHERE job_id=? AND status='pending' AND proposed_action='remove'{$where} ORDER BY id LIMIT {$limit}";$q=$pdo->prepare($sql);$q->execute(array_merge([$id],$selected));$rows=$q->fetchAll()?:[];$run=dbrepair_uuid();$pdo->beginTransaction();try{foreach($rows as $issue){$match=(int)$issue['match_id'];$before=dbrepair_details($pdo,$club,$match);$log=$pdo->prepare("INSERT INTO p2k_tp_consistency_repairs(repair_run_id,club_slug,match_id,action,reason,before_json,after_json,created_at) VALUES(?,?,?,'remove',?,?,NULL,UTC_TIMESTAMP())");$log->execute([$run,$club,$match,$issue['reason'],json_encode($before,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);$pdo->prepare("UPDATE p2k_tp_match_metadata SET result='unknown',competition_points=0,finalized_at=NULL,last_verified_at=UTC_TIMESTAMP(),next_detail_check_at=UTC_TIMESTAMP() WHERE club_slug=? AND match_id=?")->execute([$club,$match]);$pdo->prepare("UPDATE p2k_tp_boards b JOIN p2k_tp_members u ON u.member_id=b.member_id SET b.state='newly_discovered',b.next_check_at=UTC_TIMESTAMP(),b.last_error='Queued by database consistency repair' WHERE u.club_slug=? AND b.match_id=?")->execute([$club,$match]);$pdo->prepare("UPDATE p2k_tp_audit_issues SET status='repaired',updated_at=UTC_TIMESTAMP() WHERE id=?")->execute([(int)$issue['id']]);}dbrepair_rebuild($pdo,$club);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}dbrepair_json(['ok'=>true,'repaired'=>count($rows),'repair_run_id'=>$run]+dbrepair_status($pdo,dbrepair_job($pdo,$id,$club))); }
  throw new RuntimeException('Unknown action.');
 }catch(Throwable $e){dbrepair_json(['ok'=>false,'error'=>$e->getMessage()],500);}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Team Points database repair</title><style>
:root{color-scheme:dark;--gold:#f6b73c;--orange:#d98d18;--muted:#aaa198;--line:#ffffff19;--red:#ff8b79;--green:#91e09a}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;padding:18px;background:#100f0e;color:#eee;font:14px Arial,sans-serif}.shell{max-width:1180px;margin:auto}.card{margin-bottom:12px;padding:15px;border:1px solid var(--line);border-radius:11px;background:linear-gradient(145deg,#27231f,#191715)}h1,h2{margin:0;color:var(--gold)}p{color:var(--muted);line-height:1.5}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.metric{padding:10px;border:1px solid var(--line);border-radius:8px;background:#0003}.metric span,.metric strong{display:block}.metric span{color:var(--muted);font-size:10px;text-transform:uppercase}.metric strong{margin-top:4px;font-size:21px}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:11px}button,select,input{min-height:38px;padding:8px 11px;border:1px solid #ffffff2b;border-radius:8px;background:#151311;color:#eee;font:inherit}button{font-weight:850;cursor:pointer}.primary{border-color:#f6b73c77;background:var(--orange)}.danger{color:#ffb0a4;border-color:#d94a3a66}.good{color:var(--green)}.bad{color:var(--red)}.status{margin-top:10px;color:#c9e3ee}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:8px}table{width:100%;min-width:850px;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #ffffff12;text-align:left}th{color:#ffd078}td small{display:block;color:var(--muted);margin-top:3px}.token{display:grid;grid-template-columns:minmax(250px,1fr) auto;gap:7px}.help{padding:10px;border:1px solid #79c7e833;border-radius:8px;background:#79c7e80b;color:#c9e3ee}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}.token{grid-template-columns:1fr}}
</style></head><body><div class="shell"><section class="card"><h1>Team Points database consistency &amp; repair</h1><p>Persistent, resumable audits. Successful checks only advance counters; the table contains possible issues and API errors only.</p><div class="token"><input id="token" type="password" placeholder="Administrator token"><button id="saveToken">Use token</button></div></section><section class="card"><div class="help"><strong>Arithmetic audit:</strong> local-only and fast. <strong>Former-member audit:</strong> Chess.com checks only summaries involving former members. <strong>Complete audit:</strong> authoritative status check for every summary.</div><div class="actions"><select id="mode"><option value="arithmetic">Fast arithmetic audit</option><option value="former">Former-member status audit</option><option value="full">Complete authoritative audit</option></select><button class="primary" id="start">Start new audit</button><button id="latest">Load latest audit</button><button id="pause">Pause safely</button><button id="resume">Resume</button><button class="danger" id="cancel">Cancel</button><select id="batch"><option>1</option><option selected>5</option><option>10</option><option>25</option></select><button id="step">Check next batch</button><button id="auto">Run continuously</button></div><div class="status" id="status">No audit loaded.</div></section><section class="grid"><div class="metric"><span>Status</span><strong id="mStatus">—</strong></div><div class="metric"><span>Checked</span><strong id="mChecked">—</strong></div><div class="metric"><span>Total</span><strong id="mTotal">—</strong></div><div class="metric"><span>Issues</span><strong id="mIssues">—</strong></div><div class="metric"><span>API/errors</span><strong id="mErrors">—</strong></div></section><section class="card"><div class="actions"><button id="selectAll">Select visible</button><button class="primary" data-fix="1">Fix 1</button><button class="primary" data-fix="5">Fix next 5</button><button class="primary" data-fix="10">Fix next 10</button><button class="primary" data-fix="25">Fix next 25</button><button class="primary" id="fixSelected">Fix selected</button></div><div class="tablewrap"><table><thead><tr><th></th><th>Match</th><th>Issue</th><th>Action</th><th>Reason</th></tr></thead><tbody id="issues"><tr><td colspan="5">No issues detected.</td></tr></tbody></table></div></section></div><script>
(()=>{'use strict';const $=id=>document.getElementById(id),JOB_KEY='p2k_tp_database_repair_job';let job=null,auto=false,busy=false;const token=()=>sessionStorage.getItem('p2k_tp_admin_token')||$('token').value.trim();$('token').value=sessionStorage.getItem('p2k_tp_admin_token')||'';$('saveToken').onclick=()=>{sessionStorage.setItem('p2k_tp_admin_token',$('token').value.trim());$('status').textContent='Token saved for this browser tab.'};async function call(action,body={}){const r=await fetch(`?action=${encodeURIComponent(action)}`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-P2K-Admin-Token':token()},body:JSON.stringify(body)});let j={};try{j=await r.json()}catch(_){throw new Error(`HTTP ${r.status}: invalid server response`)}if(!r.ok||j.ok===false)throw new Error(j.error||`HTTP ${r.status}`);return j}function render(data){job=data.job||null;if(job)localStorage.setItem(JOB_KEY,job.id);const issues=data.issues||[];$('mStatus').textContent=job?.status||'—';$('mChecked').textContent=job?.checked_count||0;$('mTotal').textContent=job?.total_candidates||0;$('mIssues').textContent=data.pending_count??issues.length;$('mErrors').textContent=job?.error_count||0;$('status').className='status';$('status').textContent=job?`${job.mode} audit · cursor ${job.cursor_match_id} · ${data.pending_count??issues.length} unresolved issue(s).`:'No audit loaded.';$('issues').innerHTML=issues.length?issues.map(x=>`<tr><td><input class="issue" type="checkbox" value="${x.id}" ${x.proposed_action==='review'?'disabled':''}></td><td><a href="https://www.chess.com/club/matches/${x.match_id}" target="_blank" rel="noopener">${x.match_id}</a></td><td>${x.issue_type}</td><td>${x.proposed_action}</td><td>${x.reason}</td></tr>`).join(''):'<tr><td colspan="5">No possible issues are waiting for action.</td></tr>'}async function run(action,body={}){if(busy)return null;busy=true;try{const d=await call(action,body);render(d);return d}catch(e){$('status').textContent=`${e.message}. The server-side audit state was preserved; use Resume or Load latest audit.`;$('status').className='status bad';throw e}finally{busy=false}}async function loadLatest(){const saved=localStorage.getItem(JOB_KEY);if(saved){try{return await run('status',{job_id:saved})}catch(_){}}return run('latest',{})}$('start').onclick=async()=>{const d=await run('start',{mode:$('mode').value});job=d?.job||job};$('latest').onclick=loadLatest;$('pause').onclick=()=>{auto=false;$('auto').textContent='Run continuously';if(job)run('pause',{job_id:job.id})};$('resume').onclick=()=>job?run('resume',{job_id:job.id}):loadLatest();$('cancel').onclick=()=>job&&confirm('Cancel this audit?')&&(auto=false,run('cancel',{job_id:job.id}));$('step').onclick=()=>job&&run('step',{job_id:job.id,batch:Number($('batch').value)});$('auto').onclick=async()=>{if(!job)await loadLatest();if(!job)return;auto=!auto;$('auto').textContent=auto?'Stop after current batch':'Run continuously';if(auto&&job.status!=='running')await run('resume',{job_id:job.id});while(auto&&job?.status==='running'){try{const d=await run('step',{job_id:job.id,batch:Number($('batch').value)});if(!d||d.job.status!=='running')auto=false}catch(_){auto=false}if(auto)await new Promise(r=>setTimeout(r,350))}$('auto').textContent='Run continuously'};$('selectAll').onclick=()=>document.querySelectorAll('.issue:not(:disabled)').forEach(x=>x.checked=true);document.querySelectorAll('[data-fix]').forEach(b=>b.onclick=()=>job&&run('repair',{job_id:job.id,limit:Number(b.dataset.fix)}));$('fixSelected').onclick=()=>{const ids=[...document.querySelectorAll('.issue:checked')].map(x=>Number(x.value));if(job&&ids.length)run('repair',{job_id:job.id,issue_ids:ids,limit:25})};if(token())loadLatest().catch(()=>{});})();
</script></body></html>
